import{_ as a,o as s,c as n,a1 as t}from"./chunks/framework.Ccs17H5l.js";const h=JSON.parse('{"title":"Getting Started","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md"}'),o={name:"guide/index.md"};function i(r,e,l,c,p,d){return s(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h1><p>Create a new project powered by Eadkp.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>Docker (On Windows, install Docker Desktop on Windows and not in WSL)</li><li>Git (On Windows, install Git in WSL)</li></ul><h2 id="creation" tabindex="-1">Creation <a class="header-anchor" href="#creation" aria-label="Permalink to &quot;Creation&quot;">​</a></h2><p>To simplify project creation, we will use an automation script that builds a base project for us.</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki dark-plus vp-code" tabindex="0"><code><span class="line"><span style="color:#DCDCAA;">bash</span><span style="color:#CE9178;"> &lt;(</span><span style="color:#DCDCAA;">curl</span><span style="color:#569CD6;"> -s</span><span style="color:#CE9178;"> https://raw.githubusercontent.com/Oignontom8283/eadkp_template/main/bootstrap.sh)</span><span style="color:#569CD6;"> --name</span><span style="color:#CE9178;"> &quot;my_app&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki dark-plus vp-code" tabindex="0"><code><span class="line"><span style="color:#DCDCAA;">cd</span><span style="color:#CE9178;"> my_app</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>On Windows, use WSL and run the commands in WSL.</p></div><h2 id="launch" tabindex="-1">Launch <a class="header-anchor" href="#launch" aria-label="Permalink to &quot;Launch&quot;">​</a></h2><p>The base project uses Docker to simplify installation of the environment required to run the application.</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki dark-plus vp-code" tabindex="0"><code><span class="line"><span style="color:#DCDCAA;">chmod</span><span style="color:#CE9178;"> +x</span><span style="color:#CE9178;"> ./docker.sh</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki dark-plus vp-code" tabindex="0"><code><span class="line"><span style="color:#DCDCAA;">./docker.sh</span><span style="color:#CE9178;"> start</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Docker includes many dependencies, so the first build can take a long time. Please be patient.</p></div><h2 id="accessing-the-docker-container" tabindex="-1">Accessing the docker container <a class="header-anchor" href="#accessing-the-docker-container" aria-label="Permalink to &quot;Accessing the docker container&quot;">​</a></h2><p>Once the Docker container is running, to start developing you need to enter the container.</p><h3 id="vscode" tabindex="-1">VSCode <a class="header-anchor" href="#vscode" aria-label="Permalink to &quot;VSCode&quot;">​</a></h3><p>Recommended to install the <a href="https://marketplace.visualstudio.com/items?itemName=ms-vscode-remote.vscode-remote-extensionpack" target="_blank" rel="noreferrer">Remote Development</a> extension pack in Visual Studio Code or <a href="https://marketplace.visualstudio.com/items?itemName=ms-vscode-remote.remote-containers" target="_blank" rel="noreferrer">this</a> extension.</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki dark-plus vp-code" tabindex="0"><code><span class="line"><span style="color:#DCDCAA;">./docker.sh</span><span style="color:#CE9178;"> open</span><span style="color:#CE9178;"> code</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>This will open VSCode directly in the Docker container via Remote Development.</p><p>You can now work inside your Docker container as if you were working on your local machine.</p><h3 id="terminal" tabindex="-1">Terminal <a class="header-anchor" href="#terminal" aria-label="Permalink to &quot;Terminal&quot;">​</a></h3><p>In your terminal, use the script to access the Docker container.</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki dark-plus vp-code" tabindex="0"><code><span class="line"><span style="color:#DCDCAA;">./docker.sh</span><span style="color:#CE9178;"> shell</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div>',24)])])}const m=a(o,[["render",i]]);export{h as __pageData,m as default};
